package cli

import (
	"context"
	"fmt"
	"io"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

type spikeRow struct {
	Label  string
	Tokens int
	Calls  int
}

// spikeAttribute is a throwaway probe: read each session's transcript, attribute
// per-call usage to the tool that consumed it, aggregate by tool+detail.
func spikeAttribute(ctx context.Context, store checkpoint.PersistentStore, cpID id.CheckpointID, metas []*checkpoint.Metadata) []spikeRow {
	byLabel := map[string]*spikeRow{}
	for i, meta := range metas {
		if meta == nil {
			continue
		}
		ag, err := agent.GetByAgentType(meta.Agent)
		if err != nil {
			continue
		}
		attr, ok := agent.AsTokenAttributor(ag)
		if !ok {
			continue
		}
		content, err := store.ReadSessionContent(ctx, cpID, i)
		if err != nil || content == nil || len(content.Transcript) == 0 {
			continue
		}
		got, err := attr.AttributeTokens(content.Transcript, meta.TokenTranscriptStart, "")
		if err != nil || got == nil {
			continue
		}
		for _, call := range got.Calls {
			total := call.Usage.InputTokens + call.Usage.CacheCreationTokens +
				call.Usage.CacheReadTokens + call.Usage.OutputTokens
			label := "(no tool)"
			for _, c := range call.Consumed {
				label = c.ToolUse.Tool
				if c.ToolUse.Detail != "" {
					label += " " + c.ToolUse.Detail
				}
				break
			}
			if call.ActiveSkill != "" && label == "(no tool)" {
				label = "Skill: " + call.ActiveSkill
			}
			r := byLabel[label]
			if r == nil {
				r = &spikeRow{Label: label}
				byLabel[label] = r
			}
			r.Tokens += total
			r.Calls++
		}
	}
	rows := make([]spikeRow, 0, len(byLabel))
	for _, r := range byLabel {
		rows = append(rows, *r)
	}
	sort.Slice(rows, func(a, b int) bool { return rows[a].Tokens > rows[b].Tokens })
	return rows
}

func writeSpikeRows(w io.Writer, rows []spikeRow, total int) {
	if len(rows) == 0 {
		return
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Where the tokens went")
	shown := rows
	if len(shown) > 8 {
		shown = shown[:8]
	}
	for _, r := range shown {
		pct := 0
		if total > 0 {
			pct = int(float64(r.Tokens)*100/float64(total) + 0.5)
		}
		fmt.Fprintf(w, "  %-46s %10s %5d%%  (%d calls)\n",
			truncSpike(r.Label, 46), formatTokenCount(r.Tokens), pct, r.Calls)
	}
}

func truncSpike(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n-1] + "…"
}
