// spikeRecommendations is the point of the whole exercise: recommendations
// derived from what actually consumed the tokens, not from class ratios.
func spikeRecommendations(rows []spikeRow, total int) []string {
	if total == 0 {
		return nil
	}
	byProg := map[string]*spikeRow{}
	for _, r := range rows {
		prog := r.Label
		if fields := strings.Fields(r.Label); len(fields) > 1 && fields[0] == "Bash" {
			prog = "Bash " + fields[1]
		} else if len(fields) > 0 {
			prog = fields[0]
		}
		p := byProg[prog]
		if p == nil {
			p = &spikeRow{Label: prog}
			byProg[prog] = p
		}
		p.Tokens += r.Tokens
		p.Calls += r.Calls
	}

	var out []string

	// Shell file-reading: each call replays the whole context, so many small
	// reads cost far more than the bytes they return.
	readers := []string{"Bash head", "Bash tail", "Bash cut", "Bash sed", "Bash wc", "Bash cat"}
	var readTok, readCalls int
	for _, k := range readers {
		if p := byProg[k]; p != nil {
			readTok += p.Tokens
			readCalls += p.Calls
		}
	}
	if readCalls > 0 && readTok*100/total >= 15 {
		out = append(out, fmt.Sprintf(
			"Reading files through the shell (head/tail/cut/sed/wc/cat) cost %s tokens over %d calls — %d%% of this checkpoint. Each call replays the whole context, so the cost is in the number of calls, not the bytes read: use one read per file, or fetch the ranges you need in a single call.",
			formatTokenCount(readTok), readCalls, readTok*100/total))
	}

	// Single dominant tool.
	var top *spikeRow
	for _, p := range byProg {
		if p.Label != "(no tool)" && (top == nil || p.Tokens > top.Tokens) {
			top = p
		}
	}
	if top != nil && top.Tokens*100/total >= 12 {
		out = append(out, fmt.Sprintf(
			"%s alone is %d%% of the checkpoint (%s tokens over %d calls, ~%s per call). If those calls are exploratory, collapse them into fewer, wider ones.",
			top.Label, top.Tokens*100/total, formatTokenCount(top.Tokens), top.Calls,
			formatTokenCount(top.Tokens/max(top.Calls, 1))))
	}

	// Unattributable share — state it rather than implying full coverage.
	if p := byProg["(no tool)"]; p != nil && p.Tokens*100/total >= 20 {
		out = append(out, fmt.Sprintf(
			"%d%% of tokens (%s) were spent on calls with no tool use — reasoning and replies rather than tool output. Tool-level advice cannot reduce that share.",
			p.Tokens*100/total, formatTokenCount(p.Tokens)))
	}
	return out
}

func writeSpikeRecommendations(w io.Writer, rows []spikeRow, total int) {
	recs := spikeRecommendations(rows, total)
	if len(recs) == 0 {
		return
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Recommendations (attribution-driven)")
	for _, r := range recs {
		fmt.Fprintf(w, "- %s\n", r)
	}
}
